ALTER TABLE "payroll"."reimbursements" ADD CONSTRAINT "reimbursements_paid_sod_check" CHECK ("payroll"."reimbursements"."status" <> 'PAID' OR ("payroll"."reimbursements"."paid_by" IS NOT NULL AND "payroll"."reimbursements"."decided_by" IS NOT NULL AND "payroll"."reimbursements"."paid_by" <> "payroll"."reimbursements"."decided_by" AND "payroll"."reimbursements"."paid_at" IS NOT NULL));